// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class LmdbNativePosteriorStoreTest {

	private static final LmdbNativePosteriorConfig CONFIG = LmdbNativePosteriorConfig.defaults();
	private static final LmdbNativeRegimeKey WARM = LmdbNativeRegimeKey.STEADY;
	private static final LmdbNativeRegimeKey BUILDING = new LmdbNativeRegimeKey(
			LmdbNativeRegimeKey.Phase.BUILDING, 0L, false, 0L);

	private static LmdbNativePhysicalVariantKey variant(String family, int cardinalityBucket) {
		return LmdbNativePhysicalVariantKey.builder(family)
				.cardinalityBucket(cardinalityBucket)
				.build();
	}

	private static LmdbNativeCostPosteriorStore.ExactKey key(LmdbNativeRegimeKey regime, String family) {
		return LmdbNativeCostPosteriorStore.ExactKey.of(regime, LmdbNativeCostPosteriorStore.Lane.DIRECT,
				variant(family, 3));
	}

	@Test
	void completedUpdatesConvergeOnTheObservedMeanAndShrinkVarianceToTheFloors() {
		LmdbNativeCostPosteriorStore store = new LmdbNativeCostPosteriorStore(CONFIG);
		LmdbNativeCostPosteriorStore.ExactKey key = key(WARM, "nestedLoop");
		double target = Math.log(2.0);
		for (int i = 0; i < 200; i++) {
			store.updateCompleted(key, target, 1.0, 0L, 1_000L);
		}
		LmdbNativeCostPosteriorStore.Reading reading = store.read(key, 0L, 1_000L);
		assertTrue(Math.abs(reading.meanLog() - target) < 0.05,
				"mean should converge on ln 2, was " + reading.meanLog());
		double floorSum = CONFIG.varianceFloorExact() + CONFIG.varianceFloorFamily() + CONFIG.varianceFloorGlobal();
		assertTrue(reading.epistemicVariance() <= floorSum * 1.5,
				"epistemic variance should approach the floors, was " + reading.epistemicVariance());
		assertTrue(reading.epistemicVariance() >= floorSum, "variance floors must hold");
		assertTrue(reading.nEff() > 50, "effective evidence should accumulate, was " + reading.nEff());
		assertEquals(200, reading.exact().completedCount);
		assertTrue(reading.noiseVariance() >= CONFIG.noiseFloorLog(), "noise never collapses to zero");
	}

	@Test
	void oneObservationSplitsItsInnovationProportionallyToLevelUncertainty() {
		LmdbNativeCostPosteriorStore store = new LmdbNativeCostPosteriorStore(CONFIG);
		LmdbNativeCostPosteriorStore.ExactKey key = key(WARM, "hashJoin");
		store.updateCompleted(key, 1.0, 1.0, 0L, 1_000L);
		LmdbNativeCostPosteriorStore.Reading reading = store.read(key, 0L, 1_000L);
		double exactShift = reading.exact().meanLog;
		double familyShift = reading.family().meanLog;
		double globalShift = reading.global().meanLog;
		// prior variances 1.0 / 0.5 / 0.25: the exact node absorbs 2x the family share, 4x the global share
		assertTrue(exactShift > 0 && familyShift > 0 && globalShift > 0);
		assertEquals(2.0, exactShift / familyShift, 0.01);
		assertEquals(4.0, exactShift / globalShift, 0.01);
	}

	@Test
	void censoredUpdateRaisesTheMeanRetainsMoreVarianceAndCountsSeparately() {
		LmdbNativeCostPosteriorStore censored = new LmdbNativeCostPosteriorStore(CONFIG);
		LmdbNativeCostPosteriorStore.ExactKey key = key(WARM, "wcoj");
		censored.updateCensored(key, 1.0, 0L, 1_000L);
		LmdbNativeCostPosteriorStore.Reading censoredReading = censored.read(key, 0L, 1_000L);

		LmdbNativeCostPosteriorStore completed = new LmdbNativeCostPosteriorStore(CONFIG);
		completed.updateCompleted(key, 1.0, 1.0, 0L, 1_000L);
		LmdbNativeCostPosteriorStore.Reading completedReading = completed.read(key, 0L, 1_000L);

		assertTrue(censoredReading.meanLog() > 0.0, "a censoring at +1 must raise the mean above the prior");
		assertTrue(censoredReading.epistemicVariance() > completedReading.epistemicVariance(),
				"a censoring is weaker evidence than a completion");
		assertEquals(1, censoredReading.exact().censoredCount);
		assertEquals(0, censoredReading.exact().completedCount);
		double weight = censoredReading.exact().weightSum;
		assertTrue(weight >= 0.1 && weight <= 1.0, "censor weight clamps to [0.1,1], was " + weight);
		assertEquals(censoredReading.exact().noiseVariance, CONFIG.noiseInitialLog(),
				"censoring must not touch intrinsic noise");
	}

	@Test
	void buildingRegimeObservationsNeverTouchSteadyStatePosteriors() {
		LmdbNativeCostPosteriorStore store = new LmdbNativeCostPosteriorStore(CONFIG);
		LmdbNativePhysicalVariantKey variant = variant("nestedLoop", 3);
		LmdbNativeCostPosteriorStore.ExactKey buildingKey = LmdbNativeCostPosteriorStore.ExactKey
				.of(BUILDING, LmdbNativeCostPosteriorStore.Lane.DIRECT, variant);
		for (int i = 0; i < 50; i++) {
			store.updateCompleted(buildingKey, 5.0, 1.0, 0L, 1_000L);
		}
		LmdbNativeCostPosteriorStore.ExactKey warmKey = LmdbNativeCostPosteriorStore.ExactKey
				.of(WARM, LmdbNativeCostPosteriorStore.Lane.DIRECT, variant);
		LmdbNativeCostPosteriorStore.Reading warm = store.read(warmKey, 0L, 1_000L);
		assertFalse(warm.anyEvidence(), "BUILDING evidence must not leak into WARM_STABLE");
		assertEquals(0.0, warm.meanLog());
	}

	@Test
	void familyEvidenceNarrowsANewVariantWithoutPretendingExactObservationsExist() {
		LmdbNativeCostPosteriorStore store = new LmdbNativeCostPosteriorStore(CONFIG);
		LmdbNativeCostPosteriorStore.ExactKey measured = LmdbNativeCostPosteriorStore.ExactKey
				.of(WARM, LmdbNativeCostPosteriorStore.Lane.DIRECT, variant("hashJoin", 3));
		for (int i = 0; i < 100; i++) {
			store.updateCompleted(measured, 2.0, 1.0, 0L, 1_000L);
		}
		LmdbNativeCostPosteriorStore.ExactKey sibling = LmdbNativeCostPosteriorStore.ExactKey
				.of(WARM, LmdbNativeCostPosteriorStore.Lane.DIRECT, variant("hashJoin", 7));
		LmdbNativeCostPosteriorStore.Reading reading = store.read(sibling, 0L, 1_000L);
		assertTrue(reading.familyPresent());
		assertFalse(reading.exactPresent());
		// the 4:2:1 level-variance ratios put ~3/7 of the learned mean in the shared family+global nodes
		assertTrue(reading.meanLog() > 0.5, "family evidence should pull the sibling's mean, was " + reading.meanLog());
		LmdbNativeCostPosteriorStore.ExactKey stranger = LmdbNativeCostPosteriorStore.ExactKey
				.of(WARM, LmdbNativeCostPosteriorStore.Lane.DIRECT, variant("packedFtree", 3));
		LmdbNativeCostPosteriorStore.Reading strangerReading = store.read(stranger, 0L, 1_000L);
		assertTrue(strangerReading.epistemicVariance() > reading.epistemicVariance(),
				"an unseen family must be more uncertain than a measured one");
	}

	@Test
	void precisionDecaysBackTowardThePriorWhileTheMeanIsRetained() {
		LmdbNativeCostPosteriorStore store = new LmdbNativeCostPosteriorStore(CONFIG);
		LmdbNativeCostPosteriorStore.ExactKey key = key(WARM, "batch");
		for (int i = 0; i < 50; i++) {
			store.updateCompleted(key, 1.5, 1.0, 0L, 1_000L);
		}
		LmdbNativeCostPosteriorStore.Reading fresh = store.read(key, 0L, 1_000L);
		long tenHalfLives = 1_000L + 10 * CONFIG.decayHalfLifeMillis();
		LmdbNativeCostPosteriorStore.Reading stale = store.read(key, 0L, tenHalfLives);
		assertEquals(fresh.meanLog(), stale.meanLog(), 1e-9, "decay must not move the mean");
		assertTrue(stale.epistemicVariance() > fresh.epistemicVariance() * 5,
				"ten half-lives must substantially restore uncertainty");
		assertTrue(stale.nEff() < fresh.nEff() / 100, "effective evidence must age with precision");
	}

	@Test
	void anEpochBumpInflatesExactUncertaintyWithoutErasingTheMean() {
		LmdbNativeCostPosteriorStore store = new LmdbNativeCostPosteriorStore(CONFIG);
		LmdbNativeCostPosteriorStore.ExactKey key = key(WARM, "irKernel");
		for (int i = 0; i < 50; i++) {
			store.updateCompleted(key, 1.0, 1.0, 0L, 1_000L);
		}
		LmdbNativeCostPosteriorStore.Reading before = store.read(key, 0L, 1_000L);
		LmdbNativeCostPosteriorStore.Reading after = store.read(key, 1L, 1_000L);
		assertEquals(before.meanLog(), after.meanLog(), 1e-9);
		assertTrue(after.exact().epistemicVariance >= before.exact().epistemicVariance * 4.0
				|| after.exact().epistemicVariance >= CONFIG.varianceFloorExact() * 8.0,
				"epoch bump must inflate exact variance");
	}

	@Test
	void oneOutlierCannotSwingTheposteriorPastTheHuberClip() {
		LmdbNativeCostPosteriorStore store = new LmdbNativeCostPosteriorStore(CONFIG);
		LmdbNativeCostPosteriorStore.ExactKey key = key(WARM, "factorized");
		for (int i = 0; i < 100; i++) {
			store.updateCompleted(key, 0.0, 1.0, 0L, 1_000L);
		}
		LmdbNativeCostPosteriorStore.Reading before = store.read(key, 0L, 1_000L);
		double sigma = Math.sqrt(before.epistemicVariance() + before.noiseVariance());
		store.updateCompleted(key, 50.0, 1.0, 0L, 1_000L);
		LmdbNativeCostPosteriorStore.Reading after = store.read(key, 0L, 1_000L);
		double shift = after.meanLog() - before.meanLog();
		assertTrue(shift <= CONFIG.huberSigmas() * sigma + 1e-9,
				"a 50-log outlier must be clipped; shift was " + shift + " vs sigma " + sigma);
	}

	@Test
	void admissionCapsExactVariantsPerRegimeAndLaneButFamilyStillLearns() {
		LmdbNativeCostPosteriorStore store = new LmdbNativeCostPosteriorStore(CONFIG);
		int over = LmdbNativeCostPosteriorStore.MAX_VARIANTS_PER_SUBPOPULATION + 5;
		for (int i = 0; i < over; i++) {
			LmdbNativeCostPosteriorStore.ExactKey key = LmdbNativeCostPosteriorStore.ExactKey
					.of(WARM, LmdbNativeCostPosteriorStore.Lane.DIRECT, variant("flood", i));
			store.updateCompleted(key, 1.0, 1.0, 0L, 1_000L);
		}
		LmdbNativeCostPosteriorStore.ExactKey overflow = LmdbNativeCostPosteriorStore.ExactKey
				.of(WARM, LmdbNativeCostPosteriorStore.Lane.DIRECT, variant("flood", over - 1));
		LmdbNativeCostPosteriorStore.Reading reading = store.read(overflow, 0L, 1_000L);
		assertFalse(reading.exactPresent(), "past the cap, new exact variants must not be admitted");
		assertTrue(reading.familyPresent(), "the family aggregate keeps learning past the cap");
		assertEquals(LmdbNativeCostPosteriorStore.MAX_VARIANTS_PER_SUBPOPULATION,
				store.admittedVariants(overflow.subPopulation()));
	}

	@Test
	void exactKeysQuantizeTheConsumptionBucketToDeciles() {
		LmdbNativePhysicalVariantKey eightySeven = variant("nestedLoop", 3).toBuilder()
				.consumptionFractionBucket(87)
				.build();
		LmdbNativePhysicalVariantKey eightyThree = variant("nestedLoop", 3).toBuilder()
				.consumptionFractionBucket(83)
				.build();
		LmdbNativeCostPosteriorStore.ExactKey a = LmdbNativeCostPosteriorStore.ExactKey.of(WARM,
				LmdbNativeCostPosteriorStore.Lane.DIRECT, eightySeven);
		LmdbNativeCostPosteriorStore.ExactKey b = LmdbNativeCostPosteriorStore.ExactKey.of(WARM,
				LmdbNativeCostPosteriorStore.Lane.DIRECT, eightyThree);
		assertEquals(a, b, "83 and 87 both land in the 80s decile");
		assertEquals(80, a.variant().consumptionFractionBucket());
	}
}
